typedef unsigned short uint16;
typedef unsigned int uint32;

class vector3d
{
public:
  float x, y, z;
};

class vector2d
{
public:
  vector2d(float _x, float _y) : x(_x), y(_y) {}
  float x, y;
};

typedef vector2d texture_coord;

class color32
{
public:
  uint32 value;
};

class matrix4x4
{
public:
  float value[4][4];
};

enum map_e
{
  MAP_DIFFUSE
};

enum lock_type_t
{
  LOCK_CLEAR
};

class material
{
public:
  void send_context(int frame, map_e map, uint32 force_flags, color32 force_color);
};

class game
{
public:
  char pad[52];
  material *blank_material;

  material *get_blank_material() { return blank_material; }
};

class app
{
public:
  char pad[16];
  game *the_game;

  static app *inst();
  game *get_game() { return the_game; }
};

extern app *g_app;
inline app *app::inst() { return g_app; }

class geometry_manager
{
public:
  enum xform_t
  {
    XFORM_LOCAL_TO_WORLD
  };

  static geometry_manager *inst();
  void set_xform(xform_t type, const matrix4x4 &value);
  void set_local_to_world(const matrix4x4 &value)
  {
    set_xform(XFORM_LOCAL_TO_WORLD, value);
  }
};

extern geometry_manager *g_geometry_manager;
inline geometry_manager *geometry_manager::inst() { return g_geometry_manager; }

class hw_rasta_vert_lit
{
public:
  void set_xyz(const vector3d &point) { xyz = point; }

  vector3d xyz;
  float reserved;
  color32 diffuse;
  color32 specular;
  unsigned char bone_ids[4];
  float bone_weights[4];
  vector2d tc[2];
};

class vert_buf
{
public:
  void lock(int max_size, lock_type_t type = LOCK_CLEAR);
  void unlock();
  void *begin() { return vertices; }

private:
  uint32 reference;
  void *vertices;
  uint32 count;
  uint32 capacity;
  uint32 flags;
};

class hw_rasta
{
public:
  static hw_rasta *inst();
  void send_indexed_vertex_list(
      const vert_buf &vertices,
      int num_vertices,
      const uint16 *indices,
      int num_indices,
      uint32 flags = 0);
};

extern hw_rasta *g_hw_rasta;
inline hw_rasta *hw_rasta::inst() { return g_hw_rasta; }

extern matrix4x4 identity_matrix;
extern vert_buf vert_workspace;

__asm__(".equ g_app, 0x0045AC18");
__asm__(".equ g_geometry_manager, 0x00432868");
__asm__(".equ g_hw_rasta, 0x0040E418");
__asm__(".equ identity_matrix, 0x00578800");
__asm__(".equ vert_workspace, 0x00432928");
__asm__(".equ send_context__8materiali5map_eUiG7color32, 0x003397B0");
__asm__(".equ set_xform__16geometry_managerQ216geometry_manager7xform_tRC9matrix4x4, 0x002CBF50");
__asm__(".equ lock__8vert_bufi11lock_type_t, 0x001E2AD8");
__asm__(".equ unlock__8vert_buf, 0x001E2BB8");
__asm__(".equ send_indexed_vertex_list__8hw_rastaRC8vert_bufiPCUsiUi, 0x001E28D8");

enum
{
  FORCE_TRANSLUCENCY = 0x100
};

void render_triangle(const vector3d &pt1, const vector3d &pt2, const vector3d &pt3,
                     color32 col, bool double_sided)
{
  static const uint16 debug_render_indices[6]=
  {
    0,1,2,   // front
    0,2,1,   // back
  };
  uint32 num_indices=double_sided ? 6 : 3;
  uint32 num_verts=3;

  app::inst()->get_game()->get_blank_material()->send_context(0, MAP_DIFFUSE, FORCE_TRANSLUCENCY);
  geometry_manager::inst()->set_local_to_world(identity_matrix);

  vert_workspace.lock(3);
  hw_rasta_vert_lit* vert_it = (hw_rasta_vert_lit*)vert_workspace.begin();

  vert_it->set_xyz(pt1);
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(0.0f,0.0f);
  ++vert_it;

  vert_it->set_xyz(pt2);
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(0.5f,0.86f);
  ++vert_it;

  vert_it->set_xyz(pt3);
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(1.0f,0.0f);
  ++vert_it;

  vert_workspace.unlock();

  // send it to the card (using list because it could be double-sided)
  hw_rasta::inst()->send_indexed_vertex_list(vert_workspace, num_verts,
                                             debug_render_indices, num_indices);
}
